WHENEVER SQLERROR CONTINUE
ALTER SESSION SET CONTAINER=FREEPDB1;
BEGIN EXECUTE IMMEDIATE 'DROP TABLE ppiq_src.CC_SAMPLE_RESULTS CASCADE CONSTRAINTS'; EXCEPTION WHEN OTHERS THEN NULL; END;
/
BEGIN EXECUTE IMMEDIATE 'DROP TABLE ppiq_src.CC_SAMPLES CASCADE CONSTRAINTS'; EXCEPTION WHEN OTHERS THEN NULL; END;
/
BEGIN EXECUTE IMMEDIATE 'DROP TABLE ppiq_src.CC_COMPONENTS CASCADE CONSTRAINTS'; EXCEPTION WHEN OTHERS THEN NULL; END;
/
BEGIN EXECUTE IMMEDIATE 'DROP TABLE ppiq_src.CC_SLABS CASCADE CONSTRAINTS'; EXCEPTION WHEN OTHERS THEN NULL; END;
/
BEGIN EXECUTE IMMEDIATE 'DROP TABLE ppiq_src.CC_HEATS CASCADE CONSTRAINTS'; EXCEPTION WHEN OTHERS THEN NULL; END;
/
BEGIN EXECUTE IMMEDIATE 'DROP TABLE ppiq_src.CC_SEQUENCES CASCADE CONSTRAINTS'; EXCEPTION WHEN OTHERS THEN NULL; END;
/
BEGIN EXECUTE IMMEDIATE 'DROP TABLE ppiq_src.CASTER_SEQUENCES CASCADE CONSTRAINTS'; EXCEPTION WHEN OTHERS THEN NULL; END;
/
WHENEVER SQLERROR EXIT SQL.SQLCODE
CREATE TABLE ppiq_src.cc_sequences (seq_id VARCHAR2(40) PRIMARY KEY, start_utc TIMESTAMP, end_utc TIMESTAMP,
 avg_speed_mpm NUMBER(6,2), crew_id VARCHAR2(8), heats_count NUMBER(3), slabs_count NUMBER(4), aborted_breakout NUMBER(1));
CREATE TABLE ppiq_src.cc_heats (heat_id VARCHAR2(40), seq_id VARCHAR2(40), ladle_id VARCHAR2(20),
 tundish_id VARCHAR2(20), mould_id VARCHAR2(20), steel_grade VARCHAR2(20), crew_id VARCHAR2(8),
 avg_cast_speed_mpm NUMBER(6,2), avg_mould_width_mm NUMBER(6,1), superheat_c NUMBER(5,1), tundish_temp_c NUMBER(6,1),
 start_utc TIMESTAMP, end_utc TIMESTAMP, PRIMARY KEY(heat_id, seq_id));
CREATE TABLE ppiq_src.cc_slabs (slab_id VARCHAR2(40) PRIMARY KEY, heat_id VARCHAR2(40), seq_id VARCHAR2(40),
 strand_id NUMBER(2), steel_grade VARCHAR2(20), cut_utc TIMESTAMP, head_width_mm NUMBER(6,1), tail_width_mm NUMBER(6,1),
 thickness_mm NUMBER(5,1), length_m NUMBER(7,2), weight_t NUMBER(7,2), tundish_heat_no NUMBER(2));
COMMIT;
SELECT COUNT(*) AS slabs FROM ppiq_src.cc_slabs;
EXIT;
